SELECT  FROM company_goods g
WHERE g.product_id = #{productId} AND g.goods_name = #{goodsName}
ORDER BY g.id FOR UPDATE

SELECT id FROM company_goods
WHERE product_id = #{productId} AND product_id IS NOT NULL AND TRIM(product_id) != ''
  AND product_type = 1 AND id != #{id}

SELECT  FROM company_goods g WHERE g.product_id IN
#{productId}
ORDER BY g.id

SELECT id FROM company_goods WHERE goods_name IN
#{name}
AND id NOT IN
#{id}
ORDER BY id FOR UPDATE
